draw:
var T = p.halfLife;
var N0 = p.n0;
var lam = Math.LN2 / T;
var span = 5 * T;
var padL = 40, padB = 30, padT = 14, padR = 12;
var X = function (x) { return padL + (W - padL - padR) * (x / span); };
var Y = function (f) { return padT + (H - padT - padB) * (1 - f); };

ctx.lineWidth = 1;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB);
ctx.stroke();

// half-life gridlines
ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.faint;
ctx.fillStyle = C.faint;
var k;
for (k = 1; k <= 4; k++) {
  var f = Math.pow(0.5, k);
  ctx.beginPath(); ctx.moveTo(padL, Y(f)); ctx.lineTo(X(k * T), Y(f)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(k * T), Y(f)); ctx.lineTo(X(k * T), H - padB); ctx.stroke();
  ctx.textAlign = "center";
  ctx.fillText(k + "T", X(k * T), H - padB + 14);
}
ctx.setLineDash([]);

ctx.textAlign = "right";
ctx.fillStyle = C.faint;
ctx.fillText("N0", padL - 6, Y(1) + 4);
ctx.fillText("N0/2", padL - 6, Y(0.5) + 4);
ctx.fillText("N0/4", padL - 6, Y(0.25) + 4);
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("nuclei left", padL + 6, padT + 2);
ctx.textAlign = "center";
ctx.fillText("time (hours)", (padL + W - padR) / 2, H - 4);

// the exponential
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
var i;
for (i = 0; i <= 200; i++) {
  var x = span * i / 200;
  var y = Math.exp(-lam * x);
  if (i === 0) ctx.moveTo(X(x), Y(y)); else ctx.lineTo(X(x), Y(y));
}
ctx.stroke();

// swept portion
var period = span * 1.25;
var tc = Math.min(t % period, span);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  var x2 = tc * i / 200;
  var y2 = Math.exp(-lam * x2);
  if (i === 0) ctx.moveTo(X(x2), Y(y2)); else ctx.lineTo(X(x2), Y(y2));
}
ctx.stroke();

var frac = Math.exp(-lam * tc);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(tc), Y(frac), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(tc), Y(frac)); ctx.lineTo(X(tc), H - padB); ctx.stroke();

var lamS = Math.LN2 / (T * 3600);
var N = N0 * 1e12 * frac;
var act = lamS * N;
out.note = "t = " + tc.toFixed(2) + " h = " + (tc / T).toFixed(2) + " half-lives   N = " +
  (N / 1e12).toFixed(3) + "e12   activity = " + (act / 1e6).toFixed(3) + " MBq";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var padL = 44, padB = 34, padT = 16, padR = 16;
var cols = 9, rows = 7;
var cw = (W - padL - padR) / cols;
var ch = (H - padT - padB) / rows;
var X = function (c) { return padL + cw * (c + 0.5); };
var Y = function (r) { return H - padB - ch * (r + 0.5); };

// grid
ctx.strokeStyle = C.faint;
var i;
for (i = 0; i <= cols; i++) {
  ctx.beginPath(); ctx.moveTo(padL + cw * i, padT); ctx.lineTo(padL + cw * i, H - padB); ctx.stroke();
}
for (i = 0; i <= rows; i++) {
  ctx.beginPath(); ctx.moveTo(padL, H - padB - ch * i); ctx.lineTo(W - padR, H - padB - ch * i); ctx.stroke();
}

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("neutron number N", (padL + W - padR) / 2, H - 6);
ctx.save();
ctx.translate(12, (padT + H - padB) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("proton number Z", 0, 0);
ctx.restore();

var arrow = function (c0, r0, c1, r1, label, lx, ly) {
  var x0 = X(c0), y0 = Y(r0), x1 = X(c1), y1 = Y(r1);
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(a - 0.4), y1 - 8 * Math.sin(a - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(a + 0.4), y1 - 8 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(label, x1 + lx, y1 + ly);
};

// the parent nucleus, centre
var pc = 4, pr = 3;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(pc), Y(pr), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("parent", X(pc), Y(pr) - 12);

arrow(pc, pr, pc - 2, pr - 2, "alpha: A-4, Z-2", 6, 4);
arrow(pc, pr, pc - 1, pr + 1, "beta minus: Z+1", 6, -4);
arrow(pc, pr, pc + 1, pr - 1, "beta plus / EC: Z-1", -110, 16);

// gamma: same square, small loop
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.arc(X(pc) + 14, Y(pr) + 14, 10, Math.PI * 0.9, Math.PI * 2.6);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("gamma: A, Z unchanged", X(pc) + 26, Y(pr) + 22);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("each square is one nuclide; one step right adds a neutron", padL + 4, padT + 12);

out.note = "alpha moves two squares down-left; beta-minus trades a neutron for a proton";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var Tp = p.parentHL, Td = p.daughterHL;
var lp = Math.LN2 / Tp, ld = Math.LN2 / Td;
var span = p.window;
var padL = 40, padB = 30, padT = 16, padR = 12;
var X = function (x) { return padL + (W - padL - padR) * (x / span); };
var Y = function (f) { return padT + (H - padT - padB) * (1 - f); };

var daughter = function (x) {
  if (Math.abs(ld - lp) < 1e-9) return lp * x * Math.exp(-lp * x);
  return ld / (ld - lp) * (Math.exp(-lp * x) - Math.exp(-ld * x));
};

// peak of the daughter
var tpk = 0;
if (Math.abs(ld - lp) > 1e-9) tpk = Math.log(ld / lp) / (ld - lp);
if (tpk < 0) tpk = 0;

// vertical scale: 1 covers parent, daughter may exceed it
var top = 1;
var i;
for (i = 0; i <= 200; i++) {
  var xx = span * i / 200;
  if (daughter(xx) > top) top = daughter(xx);
}
top = top * 1.12;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB);
ctx.stroke();

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("time (hours)", (padL + W - padR) / 2, H - 4);
ctx.textAlign = "right";
ctx.fillText("A0", padL - 6, Y(1 / top) + 4);

// parent activity
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  var x1 = span * i / 200;
  var y1 = Math.exp(-lp * x1) / top;
  if (i === 0) ctx.moveTo(X(x1), Y(y1)); else ctx.lineTo(X(x1), Y(y1));
}
ctx.stroke();

// daughter activity
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  var x2 = span * i / 200;
  var y2 = daughter(x2) / top;
  if (i === 0) ctx.moveTo(X(x2), Y(y2)); else ctx.lineTo(X(x2), Y(y2));
}
ctx.stroke();

// peak marker
if (tpk > 0 && tpk < span) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.moveTo(X(tpk), H - padB); ctx.lineTo(X(tpk), Y(daughter(tpk) / top)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(X(tpk), Y(daughter(tpk) / top), 4, 0, Math.PI * 2); ctx.fill();
  ctx.textAlign = "center";
  ctx.fillText("peak", X(tpk), Y(daughter(tpk) / top) - 9);
}

// moving time cursor
var tc = t % span;
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(tc), padT); ctx.lineTo(X(tc), H - padB); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("parent", X(span * 0.62), Y(Math.exp(-lp * span * 0.62) / top) - 8);
ctx.fillStyle = C.accent;
ctx.fillText("daughter", X(span * 0.30), Y(daughter(span * 0.30) / top) - 8);

var ratio = ld / (ld - lp);
out.note = "peak at t = " + tpk.toFixed(1) + " h; at the cursor (" + tc.toFixed(1) +
  " h) daughter/parent activity = " + (daughter(tc) / Math.exp(-lp * tc)).toFixed(3) +
  "; long-run ratio = " + (lp < ld ? ratio.toFixed(3) : "none, parent dies first");
